    #[test]
    fn test_sns_documented_string_refinements_emit_inline_and_in_definitions() {
        for with_logging_def in [false, true] {
            let mut schema = cfn_schema_for_codegen_tests("AWS::SNS::Topic");
            if with_logging_def {
                // LoggingConfig is normally list-only. Also exercise its standalone def.
                schema.edit_json(|source| {
                    source["properties"]["LoggingConfigForTest"] =
                        serde_json::json!({"$ref": "#/definitions/LoggingConfig"});
                });
            }
            let generated = generate_schema_code(&schema, &schema.type_name).unwrap();
            for (path, pattern, min, max) in [
                (
                    "TopicName",
                    r"^[A-Za-z0-9_-]+(?:\.fifo)?$",
                    Some(1),
                    Some(256),
                ),
                (
                    "LoggingConfig.SuccessFeedbackSampleRate",
                    r"^0*(?:100|[0-9]{1,2})$",
                    None,
                    None,
                ),
            ] {
                let cfn_path = path.split_once('.').map_or_else(
                    || CfnPropertyPath::new(None, path),
                    |(parent, property)| CfnPropertyPath::new(Some(parent), property),
                );
                assert!(
                    cfn_override_property(&schema, cfn_path).unwrap().is_some(),
                    "{path}"
                );
                let expected = refined_string_type(
                    "None",
                    Some(&ApprovedPattern::whole(pattern)),
                    &emit_length_option(min, max),
                    "None",
                );
                assert!(
                    generated_sns_field(&generated, path).starts_with(&expected),
                    "{path}"
                );
                if path.contains('.') {
                    assert_all_generated_struct_fields(&generated, path, &expected);
                    if with_logging_def {
                        let (_, definitions) =
                            generated.split_once("fn build_schema_def_0()").unwrap();
                        assert_all_generated_struct_fields(definitions, path, &expected);
                    }
                }
            }
            let markdown = generate_test_markdown(&schema, &schema.type_name).unwrap();
            assert!(markdown.contains("String(pattern, len: 1..=256)"));
            assert!(markdown.contains(r"| `success_feedback_sample_rate` | `String` |"));
            assert!(
                generated_sns_field(&generated, "DisplayName")
                    .starts_with("AttributeType::string()")
            );
        }
    }

    #[test]
    fn test_cloudwatch_alarm_numeric_shapes_and_evaluation_window() {
        let schema = cfn_schema_for_codegen_tests("AWS::CloudWatch::Alarm");
        assert_eq!(schema.properties.len(), 28);

        let generated = generate_schema_code(&schema, "AWS::CloudWatch::Alarm")
            .expect("CloudWatch Alarm schema generation should succeed");
        let markdown = generate_test_markdown(&schema, "AWS::CloudWatch::Alarm")
            .expect("CloudWatch Alarm markdown generation should succeed");

        for property_name in [
            "EvaluationPeriods",
            "EvaluationInterval",
            "DatapointsToAlarm",
            "Period",
        ] {
            let property = schema
                .properties
                .get(property_name)
                .expect("Alarm integer property");
            assert_eq!(
                property
                    .prop_type
                    .as_ref()
                    .and_then(TypeValue::effective_type),
                Some("integer"),
                "{property_name} must use the CloudWatch API's integer shape"
            );
            assert!(
                generated_cloudwatch_field(&generated, property_name).starts_with(
                    if property_name == "EvaluationInterval" {
                        "AttributeType::union("
                    } else {
                        "AttributeType::refined_int("
                    }
                ),
                "{property_name} must generate a constrained Int attribute: {generated}"
            );
        }

        let number_properties: Vec<&str> = schema
            .properties
            .iter()
            .filter_map(|(name, property)| {
                (property
                    .prop_type
                    .as_ref()
                    .and_then(TypeValue::effective_type)
                    == Some("number"))
                .then_some(name.as_str())
            })
            .collect();
        assert_eq!(number_properties, vec!["Threshold"]);
        assert!(
            generated.contains("AttributeSchema::optional(\"threshold\", AttributeType::float())"),
            "Threshold must remain Float: {generated}"
        );
        assert!(
            markdown.contains("### `threshold`") && markdown.contains("- **Type:** Float"),
            "Threshold docs must remain Float: {markdown}"
        );

        assert!(
            generated.contains(
                "AttributeType::struct_with_field_groups(\"EvaluationWindow\".to_string()"
            ),
            "EvaluationWindow oneOf must generate a struct: {generated}"
        );
        assert!(
            generated.contains("StructField::optional(\"sliding_window\"")
                && generated.contains("StructField::optional(\"wall_clock_window\""),
            "EvaluationWindow must expose both union members: {generated}"
        );
    }

