    #[test]
    fn test_budgets_budget_nested_identity_is_emitted_inline_and_with_def() {
        let schema = cfn_schema_for_codegen_tests("AWS::Budgets::Budget");
        let generated = generate_schema_code(&schema, &schema.type_name).unwrap();
        let identity_field = r#"StructField::optional("budget_name", AttributeType::refined_string(None, Some("^[^:\\\\]+$".to_string()), Some((Some(1), Some(100))), None)).create_only().identity()"#;
        let (inline, definitions) = generated.split_once("fn build_schema_def_0()").unwrap();
        assert_eq!(inline.matches(identity_field).count(), 1);
        assert_eq!(definitions.matches(identity_field).count(), 1);
        assert_eq!(generated.matches(".create_only().identity()").count(), 2);

        let budget_builder = inline
            .split_once("fn build_budget_attribute()")
            .unwrap()
            .1
            .split_once("schema = schema.attribute(build_budget_attribute());")
            .unwrap()
            .0;
        let (_, parent_builder) = budget_builder.rsplit_once("]))").unwrap();
        assert!(
            !parent_builder.contains(".create_only()"),
            "Budget must stay mutable"
        );
        assert!(
            !parent_builder.contains(".identity()"),
            "identity belongs on the scalar leaf"
        );

        let markdown = generate_test_markdown(&schema, &schema.type_name).unwrap();
        let name_row = markdown
            .lines()
            .find(|line| line.starts_with("| `budget_name` |"))
            .unwrap();
        assert!(name_row.contains("Create-only."));
        assert!(name_row.contains("Anonymous identifiers hash only declared identity values."));
        let budget_argument = markdown
            .split_once("### `budget`")
            .unwrap()
            .1
            .split_once("### `notifications_with_subscribers`")
            .unwrap()
            .0;
        assert!(!budget_argument.contains("**Create-only:**"));
        assert!(!budget_argument.contains("**Identity:**"));
    }

    #[test]
    fn test_identity_generation_rejects_stale_overrides_provider_populated_and_composite_fields() {
        for invalid in [
            "cached-create-only",
            "provider-populated",
            "parent-provider-populated",
            "object",
            "array",
            "missing",
        ] {
            let mut schema = cfn_schema_for_codegen_tests("AWS::Budgets::Budget");
            let expected = match invalid {
                "cached-create-only" => {
                    schema.edit_json(|source| {
                        source
                            .as_object_mut()
                            .unwrap()
                            .entry("createOnlyProperties")
                            .or_insert_with(|| serde_json::json!([]))
                            .as_array_mut()
                            .unwrap()
                            .push(serde_json::json!(
                                "/properties/Budget/BudgetName".to_string()
                            ));
                    });
                    "already create-only in the cache"
                }
                "provider-populated" | "parent-provider-populated" => {
                    schema.edit_json(|source| {
                        source
                            .as_object_mut()
                            .unwrap()
                            .entry("readOnlyProperties")
                            .or_insert_with(|| serde_json::json!([]))
                            .as_array_mut()
                            .unwrap()
                            .push(serde_json::json!(if invalid == "provider-populated" {
                                "/properties/Budget/BudgetName".to_string()
                            } else {
                                "/properties/Budget".to_string()
                            }));
                    });
                    "identity must not be provider-populated"
                }
                "object" | "array" => {
                    schema.edit_json(|source| {
                        source["definitions"]["BudgetData"]["properties"]["BudgetName"] =
                            if invalid == "object" {
                                serde_json::json!({"type": "object", "properties": {"Name": {"type": "string"}}})
                            } else {
                                serde_json::json!({"type": "array", "items": {"type": "string"}})
                            };
                    });
                    "missing string plan"
                }
                "missing" => {
                    schema.edit_json(|source| {
                        source["definitions"]["BudgetData"]["properties"]
                            .as_object_mut()
                            .unwrap()
                            .remove("BudgetName");
                    });
                    "stale identity row"
                }
                _ => unreachable!(),
            };
            for error in [
                generate_schema_code(&schema, &schema.type_name).unwrap_err(),
                generate_test_markdown(&schema, &schema.type_name).unwrap_err(),
            ] {
                let message = error.to_string();
                assert!(
                    message.contains("AWS::Budgets::Budget.BudgetData.BudgetName"),
                    "{invalid}: {message}"
                );
                assert!(message.contains(expected), "{invalid}: {message}");
            }
        }
    }

    #[test]
    fn test_budgets_budget_recursive_expression_emits_schema_ref() {
        let schema = cfn_schema_for_codegen_tests("AWS::Budgets::Budget");
        assert_eq!(schema.properties.len(), 4);

        let generated = generate_schema_code(&schema, "AWS::Budgets::Budget")
            .expect("Budgets Budget schema generation should succeed");
        let markdown = generate_test_markdown(&schema, "AWS::Budgets::Budget")
            .expect("Budgets Budget markdown generation should succeed");

        assert!(
            generated.contains("schema = schema.with_def(\"Expression\""),
            "the recursive Expression definition must be emitted once: {generated}"
        );
        assert!(
            generated.contains("AttributeType::ref_(\"Expression\".to_string())"),
            "recursive Expression edges must use AttributeType::Ref: {generated}"
        );
        for field in ["and", "or"] {
            assert!(
                generated.contains(&format!(
                    "StructField::optional(\"{field}\", AttributeType::list(AttributeType::ref_(\"Expression\".to_string())))"
                )),
                "Expression.{field} must be List<Expression>: {generated}"
            );
        }
        assert!(
            generated.contains(
                "StructField::optional(\"not\", AttributeType::ref_(\"Expression\".to_string()))"
            ),
            "Expression.Not must refer to Expression: {generated}"
        );
        assert!(
            generated.contains(
                "StructField::optional(\"tags\", AttributeType::struct_(\"TagValues\".to_string()"
            ) && !generated
                .contains("StructField::optional(\"tags\", AttributeType::map_with_key("),
            "Expression.Tags is a Budgets filter expression, not a Key/Value tag map: {generated}"
        );
        assert!(
            generated.contains("AttributeSchema::optional(\"notifications_with_subscribers\"")
                && generated.contains(".create_only()"),
            "NotificationsWithSubscribers must remain create-only: {generated}"
        );
        assert!(
            markdown.contains("Expression") && markdown.contains("filter_expression"),
            "Budget docs must include the recursive expression surface: {markdown}"
        );
    }

