    #[test]
    fn test_list_struct_mutual_cycle_emits_only_back_referenced_definition() {
        let list_of = |definition: &str| CfnProperty {
            prop_type: Some(TypeValue::Single("array".to_string())),
            items: Some(Box::new(CfnProperty {
                ref_path: Some(format!("#/definitions/{definition}")),
                ..Default::default()
            })),
            ..Default::default()
        };
        let mut schema = empty_schema("AWS::Test::ListCycle");
        schema.edit_json(|source| {
            source["properties"]
                .as_object_mut()
                .unwrap()
                .insert("Roots".to_string(), serde_json::json!(list_of("CycleA")));
        });
        schema.edit_json(|source| {
            source["definitions"] = serde_json::json!(BTreeMap::from([
                (
                    "CycleA".to_string(),
                    CfnProperty {
                        prop_type: Some(TypeValue::Single("object".to_string())),
                        properties: Some(BTreeMap::from([(
                            "Children".to_string(),
                            list_of("CycleB"),
                        )])),
                        ..Default::default()
                    },
                ),
                (
                    "CycleB".to_string(),
                    CfnProperty {
                        prop_type: Some(TypeValue::Single("object".to_string())),
                        properties: Some(BTreeMap::from([(
                            "Parents".to_string(),
                            list_of("CycleA")
                        )])),
                        ..Default::default()
                    },
                ),
            ]));
        });

        let generated = generate_synthetic_schema_code(&schema)
            .expect("a two-definition list-only cycle must terminate");
        assert!(
            generated.contains(
                "StructField::optional(\"parents\", AttributeType::list(AttributeType::ref_(\"CycleA\".to_string())))"
            ),
            "the CycleB -> CycleA back-edge must use a schema ref: {generated}"
        );
        assert_eq!(
            generated
                .matches("schema = schema.with_def(\"CycleA\"")
                .count(),
            1,
            "the referenced definition must be emitted exactly once: {generated}"
        );
        assert!(
            !generated.contains("schema = schema.with_def(\"CycleB\""),
            "an inline definition with no back-reference to itself must stay inline: {generated}"
        );
    }

    #[test]
    fn catalog_constructor_display_names_are_derived_from_catalog_identities() {
        let mut failures = Vec::new();
        for row in AwsccType::ALL {
            let constructor = row.constructor_path();
            let actual = override_type_to_display_name(constructor);
            let expected = row.identity().to_string();
            // Retain the complete table for before/after verification, including
            // catalog constructors that previously fell through to String.
            println!("CATALOG_DISPLAY\t{constructor}\t{actual}\t{expected}");
            if actual != expected {
                failures.push(format!("{constructor}: {actual:?}, expected {expected:?}"));
            }
            let identity = row.identity();
            if identity.kind == "Arn"
                && let [service, resource] = identity.segments.as_slice()
            {
                let forwarding_helper = format!(
                    "super::super::{service}::{}::arn()",
                    resource.to_snake_case()
                );
                assert_eq!(
                    override_type_to_display_name(&forwarding_helper),
                    expected,
                    "{forwarding_helper} must use its catalog constructor's display",
                );
            }
        }
        assert!(failures.is_empty(), "{}", failures.join("\n"));
    }

    fn documented_attribute_type<'a>(markdown: &'a str, attribute: &str) -> &'a str {
        let heading = format!("### `{attribute}`\n");
        let (_, section) = markdown
            .split_once(&heading)
            .unwrap_or_else(|| panic!("missing Markdown attribute {attribute}"));
        section
            .split("\n### ")
            .next()
            .unwrap()
            .lines()
            .find_map(|line| line.strip_prefix("- **Type:** "))
            .unwrap_or_else(|| panic!("missing Markdown type for {attribute}"))
    }

