    #[test]
    fn test_generate_markdown_shows_create_only() {
        let mut properties = BTreeMap::new();
        properties.insert(
            "CidrBlock".to_string(),
            CfnProperty {
                prop_type: Some(TypeValue::Single("string".to_string())),
                description: Some("The CIDR block.".to_string()),
                ..Default::default()
            },
        );
        properties.insert(
            "Name".to_string(),
            CfnProperty {
                prop_type: Some(TypeValue::Single("string".to_string())),
                description: Some("The name.".to_string()),
                ..Default::default()
            },
        );

        let schema = ParsedCfnSchema::from_json(serde_json::json!({
            "typeName": "AWS::Test::Resource".to_string(),
            "properties": properties,
            "createOnlyProperties": vec!["/properties/CidrBlock".to_string()]
        }))
        .unwrap();

        let md = generate_test_markdown(&schema, "AWS::Test::Resource").unwrap();

        assert!(
            md.contains("**Create-only:** Yes"),
            "Should show create-only annotation for CidrBlock: {md}"
        );
        // Name should NOT have create-only
        let name_section = md.split("### `name`").nth(1).unwrap_or("");
        assert!(
            !name_section
                .split("###")
                .next()
                .unwrap_or("")
                .contains("Create-only"),
            "Name should not have create-only annotation: {md}"
        );
    }

